func TestEnumWhoCanPostTypes(t *testing.T) {
	t.Run("NewFromString_everyone", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoCanPostTypesFromString("everyone")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoCanPostTypes("everyone"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_admins", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoCanPostTypesFromString("admins")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoCanPostTypes("admins"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewWhoCanPostTypesFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewWhoCanPostTypesFromString("everyone")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

